const input = $json || {};
const headers = input.headers || {};
const body = input.body || {};

const EXPECTED_SECRET = 'eagles2026';
const receivedSecret = String(headers['x-eagles-secret'] || headers['X-Eagles-Secret'] || '');
if (!receivedSecret || receivedSecret !== EXPECTED_SECRET) {
  throw new Error('Solicitud no autorizada');
}

const request = body.copy_request || {};
const clean = (value) => String(value || '').trim();
const normalize = (value) => clean(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const channels = Array.isArray(request.channels) && request.channels.length
  ? request.channels.map(clean).filter(Boolean)
  : ['Facebook', 'Instagram'];

if (!clean(request.product_topic)) throw new Error('Falta product_topic');

const categoryLabels = {
  social: 'redes sociales',
  taller: 'servicios del taller de transmisiones',
  course: 'curso o capacitación de transmisiones'
};

const facts = [
  clean(request.brief),
  clean(request.call_to_action) ? `CTA solicitado: ${clean(request.call_to_action)}` : '',
  clean(request.audience) ? `Audiencia: ${clean(request.audience)}` : '',
  clean(request.image_brief) ? `Brief visual: ${clean(request.image_brief)}` : ''
].filter(Boolean).join('\\n');

const normalizedTopic = normalize(request.product_topic);
const normalizedObjective = normalize(request.objective);
const normalizedCampaign = normalize(request.campaign_code || body.campaign_code || body.copy_request?.campaign_code);
const requestedFramework = normalize(request.copy_framework || body.framework?.name || 'AIDA');
const useAIDA = !requestedFramework || requestedFramework === 'aida';

// Detección robusta por campaña + tema + brief.
const routeText = normalize([
  request.campaign_code,
  body.campaign_code,
  request.product_topic,
  request.brief,
  request.objective
].filter(Boolean).join(' '));

const isWorkshopConvencionales =
  normalizedCampaign.includes('workshop_octubre') ||
  (routeText.includes('workshop') && routeText.includes('convencional'));

const isJF017 =
  normalizedCampaign.includes('jf017') ||
  routeText.includes('jf017') ||
  routeText.includes('jf017e') ||
  (routeText.includes('cvt') && routeText.includes('017'));
const isWhatsAppWarmup = channels.length === 1 && channels[0].toLowerCase() === 'whatsapp' && normalizedObjective.includes('calentamiento');
const hasSocialChannel = channels.some((channel) => ['facebook', 'instagram', 'tiktok'].includes(channel.toLowerCase()));

const WORKSHOP_GROUP_URL = 'https://chat.whatsapp.com/Gu955o9muhZ2eJGOaRw0wS?s=cl&p=i&mlu=4&ilr=4';
const WORKSHOP_HOTMART_URL = 'https://pay.hotmart.com/U107474945W?bid=1788557927997';
const JF017_DEFAULT_CTA = '📲 Reserva tu lugar: 449 110 7766';
const jf017CTA = clean(request.call_to_action) || JF017_DEFAULT_CTA;

let structureRules = '';

if (isWorkshopConvencionales && isWhatsAppWarmup) {
  structureRules = `\nAIDA OBLIGATORIO · WORKSHOP WHATSAPP:\nA · ATRACCIÓN: abre con un gancho corto basado en una falla, duda o situación real del técnico.\nI · INTERÉS: aporta UNA sola idea técnica útil sobre transmisiones convencionales.\nD · DESEO: conecta esa idea con lo que aprenderá o podrá comprender mejor en la Workshop, en una sola frase.\nA · ACCIÓN: cierra UNA sola vez con el CTA fijo.\n- Máximo 70 palabras antes del enlace.\n- Sin hashtags y sin repetir datos.\n- Mantén los datos confirmados en líneas separadas:\n📅 2 y 3 de octubre\n💻 Online en vivo vía Zoom\n💲 17 USD\n- Cierra UNA sola vez con:\n👉 Inscríbete aquí:\n${WORKSHOP_HOTMART_URL}\n- NO escribas las palabras Atracción, Interés, Deseo o Acción dentro del copy final.\n- El campo copy debe contener SOLO texto publicable, nunca JSON dentro del texto.`;
} else if (isWorkshopConvencionales && hasSocialChannel) {
  structureRules = `\nAIDA OBLIGATORIO · REDES WORKSHOP:\nA · ATRACCIÓN: gancho fuerte basado en un problema real del técnico/taller.\nI · INTERÉS: una idea técnica o situación que genere identificación.\nD · DESEO: explica en máximo 2 frases por qué la Workshop puede ayudarle a comprender o trabajar mejor ese tema.\nA · ACCIÓN: CTA final UNA sola vez:\n🔥 Únete al grupo y recibe toda la información para asegurar tu acceso:\n👉 ${WORKSHOP_GROUP_URL}\n- No pongas Hotmart.\n- Máximo 3 hashtags relevantes.\n- NO rotules las etapas AIDA en el copy final.\n- El campo copy debe contener SOLO texto publicable, nunca JSON dentro del texto.`;
} else if (isJF017 && isWhatsAppWarmup) {
  structureRules = `\nAIDA OBLIGATORIO · WHATSAPP CURSO CVT JF017:\n- Este flujo arma el mensaje final después de Ollama y CONSERVA la estructura de emojis ya validada.\nA · ATRACCIÓN: tú generas un gancho técnico corto que haga detenerse al transmisionista.\nI · INTERÉS: completa con UNA sola idea útil de 20 a 32 palabras en total entre gancho e idea.\nD · DESEO: n8n lo agregará después con los beneficios confirmados del curso.\nA · ACCIÓN: n8n agregará después fecha, precio y CTA.\n- Habla de UN SOLO tema: P17F0/P17F1, cuerpo de válvulas, presión hidráulica, cadena/poleas, TCM/software o deterioro térmico del aceite.\n- No pongas fechas, horarios, precio, apartado, teléfono, CTA, beneficios, hashtags ni listas.\n- No uses las palabras “calentamiento”, “campaña”, “brief”, “banco técnico” o “datos confirmados”.\n- No escribas “Curso profesional”, “únete al curso”, “reserva” o “cupos limitados”.\n- NO rotules AIDA en el copy final.\n- El campo copy debe contener SOLO texto plano; jamás metas otro JSON dentro de copy.`;
} else if (isJF017 && hasSocialChannel) {
  structureRules = `\nAIDA OBLIGATORIO · REDES CURSO CVT JF017:\nA · ATRACCIÓN: gancho técnico fuerte, sin exageración.\nI · INTERÉS: desarrolla UNA sola idea técnica o dolor real.\nD · DESEO: conecta esa idea con el beneficio concreto del curso en máximo 2 frases.\nA · ACCIÓN: CTA final UNA sola vez: ${JF017_DEFAULT_CTA}\n- Máximo 2 datos del evento en el cuerpo.\n- Máximo 4 hashtags relevantes; nunca una lista de códigos.\n- No repitas teléfono, CTA ni datos.\n- NO rotules AIDA en el copy final.\n- El campo copy debe contener SOLO texto publicable, nunca JSON dentro del texto.`;
}

const systemPrompt = `Eres copywriter senior de Eagles Digital Solutions y Eagles Gear Solutions.\n\nEscribes para técnicos, transmisionistas y dueños de taller en México. Tu estilo es humano, técnico, breve y comercial sin sonar generado por IA.\n\nMETODOLOGÍA OBLIGATORIA AIDA:\n- Atracción: abre con un gancho que detenga la atención.\n- Interés: aporta una idea útil, técnica o relevante.\n- Deseo: conecta esa idea con un beneficio concreto para la audiencia.\n- Acción: termina con un solo CTA claro.\n- Aplica AIDA de forma natural; NO escribas las etiquetas “Atracción”, “Interés”, “Deseo” o “Acción” dentro del copy.\n\nREGLAS GLOBALES:\n- Usa solo datos confirmados.\n- No inventes precio, fechas, horarios, promociones, enlaces ni garantías.\n- No prometas ingresos ni resultados económicos.\n- No hagas diagnósticos definitivos por mensaje.\n- Una idea central por copy.\n- No repitas frases, CTA, teléfonos, fechas ni bloques de información.\n- No conviertas listas técnicas en hashtags.\n- Evita relleno, clichés y frases motivacionales genéricas.\n- Respeta enlaces y números literalmente.\n- Devuelve únicamente JSON válido con las claves copy e image_prompt.\n- MUY IMPORTANTE: el valor de copy debe ser texto plano listo para publicar; jamás metas otro objeto JSON dentro de copy.${structureRules}\n\nFORMATO EXACTO:\n{"copy":"texto listo para publicar","image_prompt":"prompt visual o cadena vacía"}`;

const userPrompt = `Crea UN solo copy con estos datos:\nMetodología: ${useAIDA ? 'AIDA (Atracción, Interés, Deseo, Acción)' : clean(request.copy_framework || body.framework?.name)}\nCategoría: ${categoryLabels[request.category] || clean(request.category) || 'redes sociales'}\nTema: ${clean(request.product_topic)}\nObjetivo: ${clean(request.objective) || 'Venta'}\nCanales: ${channels.join(', ')}\nTono: ${clean(request.tone) || 'Directo y profesional'}\nRequiere imagen: ${request.needs_image === true ? 'sí' : 'no'}\nDatos confirmados:\n${facts || 'No hay datos adicionales; trabaja únicamente con el tema y las reglas confirmadas.'}`;

return [{
  json: {
    request_id: clean(body.request_id),
    campaign_detected: isWorkshopConvencionales ? 'WORKSHOP_OCTUBRE' : isJF017 ? 'CURSO_JF017_OCTUBRE' : 'GENERAL',
    framework_detected: useAIDA ? 'AIDA' : clean(request.copy_framework || body.framework?.name || 'AIDA'),
    postprocess: {
      is_jf017: isJF017,
      is_workshop: isWorkshopConvencionales,
      is_whatsapp_warmup: isWhatsAppWarmup,
      cta: isJF017 ? jf017CTA : ''
    },
    ollama_request: {
      model: 'qwen2.5:3b',
      stream: false,
      keep_alive: '30m',
      format: {
        type: 'object',
        properties: {
          copy: { type: 'string' },
          image_prompt: { type: 'string' }
        },
        required: ['copy', 'image_prompt']
      },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      options: {
        temperature: 0.25,
        num_predict: 420,
        num_ctx: 4096,
        repeat_penalty: 1.20,
        repeat_last_n: 160
      }
    }
  }
}];

let content = String($json?.message?.content ?? $json?.response ?? '').trim();
content = content.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();

function parseMaybeJson(value) {
  let current = String(value || '').trim();

  for (let i = 0; i < 4; i++) {
    try {
      const parsed = JSON.parse(current);
      if (typeof parsed === 'string') {
        current = parsed.trim();
        continue;
      }
      if (parsed && typeof parsed === 'object') return parsed;
    } catch {}

    const start = current.indexOf('{');
    const end = current.lastIndexOf('}');
    if (start !== -1 && end > start) {
      try {
        const parsed = JSON.parse(current.slice(start, end + 1));
        if (parsed && typeof parsed === 'object') return parsed;
      } catch {}
    }
    break;
  }
  return null;
}

// Recupera el campo copy incluso si Ollama cortó el JSON antes de cerrar.
function recoverCopyFromBrokenJson(value) {
  let raw = String(value || '').trim();
  const match = raw.match(/["']?copy["']?\s*:\s*"([\s\S]*)/i);
  if (!match) return raw;

  raw = match[1];

  // Quita image_prompt si alcanzó a aparecer y cierres parciales del JSON.
  raw = raw.replace(/"\s*,\s*"image_prompt"[\s\S]*$/i, '');
  raw = raw.replace(/"\s*}\s*$/i, '');
  raw = raw.replace(/\\n/g, '\n').replace(/\\"/g, '"').replace(/\\\\/g, '\\');

  return raw.trim();
}

let parsed = parseMaybeJson(content);
let copy = String(parsed?.copy ?? '').trim();
let imagePrompt = String(parsed?.image_prompt || '').trim();

if (!copy) {
  copy = recoverCopyFromBrokenJson(content);
}

// Si el modelo metió JSON otra vez dentro de copy, lo desenvolvemos.
for (let i = 0; i < 3; i++) {
  const nested = parseMaybeJson(copy);
  if (nested?.copy && String(nested.copy).trim() !== copy) {
    copy = String(nested.copy).trim();
    if (!imagePrompt) imagePrompt = String(nested.image_prompt || '').trim();
  } else {
    const recovered = recoverCopyFromBrokenJson(copy);
    if (recovered !== copy && recovered.length > 0) copy = recovered;
    break;
  }
}

copy = copy.replace(/\\n/g, '\n').replace(/\\"/g, '"').trim();

const prep = $('Validar y preparar copy').item.json;
const pp = prep?.postprocess || {};

if (pp.is_whatsapp_warmup) {
  copy = copy.replace(/(^|\s)#[\p{L}\p{N}_-]+/gu, '$1');
  copy = copy.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n');
  copy = copy.replace(/[ \t]{2,}/g, ' ').trim();
}

if (!copy) throw new Error('Ollama no devolvió un copy');

return [{
  json: {
    copy,
    image_prompt: imagePrompt,
    execution_id: String($execution.id),
    campaign_detected: String(prep?.campaign_detected || 'GENERAL')
  }
}];

const out = { ...$json };
const prep = $('Validar y preparar copy').item.json || {};
const pp = prep.postprocess || {};
const campaign = String(out.campaign_detected || prep.campaign_detected || '').trim();

// WORKSHOP Y DEMÁS CAMPAÑAS:
// pasan exactamente como vienen. Este nodo NO las modifica.
const isJF017WhatsApp =
  (campaign === 'CURSO_JF017_OCTUBRE' || pp.is_jf017 === true) &&
  pp.is_whatsapp_warmup === true;

if (!isJF017WhatsApp) {
  return [{ json: out }];
}

// ============================================================
// JF017 WHATSAPP: FORMATO CONTROLADO DE PRODUCCIÓN
// ============================================================

let raw = String(out.copy || '').trim();

// Quitar residuos internos / comerciales si Ollama ignoró el prompt.
raw = raw
  .replace(/```json|```/gi, '')
  .replace(/\{?\s*"copy"\s*:\s*"?/gi, '')
  .replace(/"\s*,?\s*"image_prompt"[\s\S]*$/gi, '')
  .replace(/\b(banco técnico(?: confirmado)?|brief|datos confirmados|campaña|calentamiento(?: técnico| en vivo)?)\b/gi, '')
  .replace(/#[\p{L}\p{N}_-]+/gu, '')
  .replace(/[ \t]{2,}/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const salesWords = /(curso|reserva|inscrib|precio|mxn|octubre|online|grabaciones|manuales|calibraciones|cupo|plaza|apart|tel[eé]fono|449\s*110\s*7766|viernes|s[aá]bado|horario|incluye|promoci[oó]n)/i;

// Buscar una oración que sí parezca técnica.
const sentences = raw
  .replace(/\n+/g, ' ')
  .split(/(?<=[.!?])\s+/)
  .map(s => s.trim())
  .filter(Boolean);

let technical = sentences.find(s =>
  s.length >= 35 &&
  s.length <= 210 &&
  !salesWords.test(s) &&
  /(jf017|cvt|p17f|presi[oó]n|polea|cadena|v[aá]lvula|tcm|software|aceite|diagn[oó]st|transmisi[oó]n)/i.test(s)
);

// Banco seguro de respaldo si Ollama vuelve a ignorar las reglas.
const fallbackTips = [
  'En una JF017, un código de falla no cuenta toda la historia: presión, cuerpo de válvulas y condición interna también orientan el diagnóstico.',
  'Antes de condenar una JF017, revisar presión hidráulica y cuerpo de válvulas puede darte información clave sobre dónde está realmente la falla.',
  'La JF017 trabaja con cadena y poleas; entender cómo cambia la relación ayuda a interpretar mejor síntomas y comportamiento de la transmisión.',
  'Un P17F1 no debe analizarse aislado: presión, cuerpo de válvulas y condición de cadena y poleas también forman parte de la evaluación.',
  'En una JF017, revisar TCM, señales y software antes de desarmar puede evitar que una falla electrónica se confunda con daño interno.',
  'La temperatura influye directamente en el deterioro del aceite; revisar condición del fluido e historial térmico aporta contexto al diagnóstico.'
];

if (!technical) {
  const seed = String(prep.request_id || out.execution_id || 'jf017');
  let hash = 0;
  for (let i = 0; i < seed.length; i++) {
    hash = ((hash << 5) - hash + seed.charCodeAt(i)) | 0;
  }
  technical = fallbackTips[Math.abs(hash) % fallbackTips.length];
}

// Limpieza final del tip.
technical = technical
  .replace(/^[-•🔥⚙️🔧\s]+/u, '')
  .replace(/\s+/g, ' ')
  .trim();

if (technical.length > 210) {
  technical = technical.slice(0, 207).trim() + '...';
}
if (!/[.!?]$/.test(technical)) technical += '.';

// Este bloque SIEMPRE será el resultado final del JF017 WhatsApp.
out.copy = [
  '⚙️ ¡CARNALITOS!',
  `🔧 ${technical}`,
  '',
  '📅 16 y 17 de octubre',
  '💻 100% online',
  '🕚 Vie 11:00 AM–5:00 PM | Sáb 11:00 AM–3:00 PM (MX)',
  '💲 $2,997 MXN | Aparta con $1,500',
  '',
  '🎁 Grabaciones + manuales de apoyo + calibraciones de regalo',
  '📲 Reserva tu lugar: 449 110 7766'
].join('\n');

return [{ json: out }];
